import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('gobernados-por-la-paz', 'B',
 [dict(t=609, e=672, titulo='«Bésame» también significa «equípame»', txt='Fíjese que, cuando usted va a ver el significado de esa palabra «bésame», en el diccionario Strong es la palabra 5401, que significa varias cosas: significa besar. Amén. Hasta ahí creo que es una petición, hermano, bastante literal. Pero fíjese que también significa equipar con armas. Es decir, cuando la novia le está diciendo al amado: «Señor, bésame», lo que le está pidiendo es: «Señor, equípame con armas». Porque, aunque va a ser la novia, hermano, viene un tiempo tal vez complicado o difícil que nos va a tocar batallar […]. «Bueno, viene un tiempo difícil antes de que me case; yo necesito estar equipada». Por eso es que la Biblia dice en Efesios que el Señor nos dejó una armadura.'),
  dict(t=1505, e=1565, titulo='Dejar que otro administre lo que puedo hacer', txt='Teníamos culto en ese momento, en la mañana y en la tarde, allá en San Felipe. Me llamó el pastor en la mañana y me dijo: «¿Cómo te fue en el partido?». «Ah», le dije, «hermano, yo nunca había ido a un estadio. Yo estaba contento, en medio de todo, porque había vivido la experiencia». […] «Ganó la Antigua», le dije. «Saliste bien contaminado, ¿verdad?». Entonces me dijo: «Te toca predicar en la tarde». Ay, me terminó de matar, hermano. Entonces yo entendí que el Espíritu me estaba hablando. Yo no soy fanático hueso colorado del fútbol. Era la primera, pero fue la última vez que fui a un estadio a ver un partido. Porque, si yo quiero que me gobiernen, tengo que dejar que otro administre lo que puedo hacer y lo que no.'),
  dict(t=2218, e=2275, titulo='La paz gobierna', txt='Pero mire, pues, Colosenses 3:15: «Y que la paz de Dios, la paz de Cristo, reine en vuestros corazones, a la cual en verdad fuisteis llamados en un solo cuerpo; y sed agradecidos». Mire, mismo verso, pero en la versión del 60: «Y la paz de Dios gobierne». Es decir, la paz gobierna. Diga conmigo: la paz gobierna en vuestros corazones, a la que fuisteis llamados en un solo cuerpo; y sed agradecidos. Entonces, ¿cuántos quieren dejarse gobernar por la paz? Okay. Dígame una señal de aquel que se deja gobernar por la paz.')],
 [dict(t=963, txt='Muchos dicen: «Yo y el Señor, mi copiloto». El Señor no tiene que ser el copiloto: el Señor tiene que ser el piloto.'),
  dict(t=1780, txt='La autoridad se expone, no se impone.'),
  dict(t=2050, txt='La paz también es algo que podemos perder fácilmente.'),
  dict(t=4206, txt='Si tú dejas que él gobierne tu vida con paz, que él dirija, que él administre tu vida, él se va a encargar de todo.')],
 ['Si le dijeras al Señor «bésame», es decir, «gobiérname», ¿en qué área concreta de tu vida todavía te cuesta soltarle el timón?',
  '¿Qué situación de todos los días, un retraso, un rayón o una mala noticia, te roba la paz con más facilidad? ¿Qué harías distinto esta semana?',
  '¿Qué puedes agradecerle hoy a Dios, aun en medio de lo que todavía no ves resuelto?'])
